#!/usr/bin/env python3
"""Re-author Year 10 Science Inquiry topic pages without changing routes/resources."""
from __future__ import annotations
import html, re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
BASE=ROOT/'year10'/'science'
PROFILES={
'AC9S10I01':{'title':'Develop Testable Explanatory Questions','summary':'Strong scientific questions identify a measurable relationship. A hypothesis proposes an evidence-based explanation, and a prediction states what should be observed if that explanation is supported.','examples':[('From observation to question','Observation: a trolley accelerates more when the pulling force increases. Question: How does net force affect acceleration when mass is kept constant?'),('Build a reasoned hypothesis','Increasing net force should increase acceleration because a larger unbalanced force produces a larger change in motion for the same mass.'),('Derive a prediction','If pulling force is doubled while mass stays constant, measured acceleration should increase.'),('Separate correlation from causation','If hotter days are associated with higher electricity use, the data show a relationship. A causal hypothesis still needs a plausible mechanism and a design that rules out alternatives.')],'mis':[('Prediction = hypothesis','A prediction is an expected result; a hypothesis is the proposed explanation that produces the prediction.'),('Every question must be causal','Descriptive and correlational questions can be investigable when variables are measurable.'),('Vague terms are measurable','Replace words such as better or more effective with a measurable quantity.'),('One supported prediction proves the model','Support increases confidence; it does not prove that no alternative explanation exists.')],'steps':[('Define the observation','State what is known or noticed without explaining it yet.'),('Name measurable variables','Identify what could change, what could be measured and what conditions matter.'),('Propose a mechanism','Use scientific knowledge to explain why a relationship may occur.'),('State a testable prediction','Describe the expected pattern and how evidence would support or challenge the hypothesis.')],'transfer':'A student notices that reaction time appears slower after sleep restriction. Write an investigable question, a reasoned hypothesis and one prediction that could be tested ethically.'},
'AC9S10I02':{'title':'Design Valid, Reproducible Investigations','summary':'A valid investigation tests the intended relationship while controlling important alternative causes. A reproducible method is transparent enough for another investigator to repeat, and it must also satisfy safety, ethical and cultural responsibilities.','examples':[('Control a confounding variable','To test light intensity and photosynthesis, keep plant species, temperature, carbon dioxide availability and measurement time consistent while varying light intensity.'),('Repeats do not fix bias','Repeating a miscalibrated sensor 50 times can produce a very consistent but systematically wrong result. Calibration must be corrected first.'),('Plan an ethical animal investigation','Before collecting animal data, minimise disturbance, justify the need for the observations and follow relevant animal-care requirements.'),('Respect Country/Place responsibilities','If an investigation involves First Nations heritage sites, artefacts or knowledge, appropriate authority and protocols must be established before access, recording or publication.')],'mis':[('More repeats make any method valid','Repeats reduce random variation; they cannot repair a design that tests the wrong variable or contains systematic bias.'),('A detailed method is automatically reproducible','It must include operational details, equipment settings, units, sampling and decision rules.'),('Safety is added after the method','Hazards and controls can change the method itself and must be planned before data collection.'),('Cultural knowledge is freely usable data','Access, permissions, attribution and restrictions must be respected; some knowledge or places may not be appropriate to record or share.')],'steps':[('Align question and variables','Make sure the variables or comparison groups answer the actual question.'),('Control alternative causes','Identify confounders and decide how each will be controlled, randomised, matched or measured.'),('Plan quality data','Choose suitable sampling, repeats, equipment, units and recording procedures.'),('Complete responsibility checks','Assess hazards, ethics, environmental impact and any Country/Place or heritage obligations before conducting the investigation.')],'transfer':'A class wants to test whether screen brightness affects battery life. Design the key variables, controls, repeats and one validity check needed for a reproducible investigation.'},
'AC9S10I03':{'title':'Collect Precise, Replicable Data','summary':'Useful scientific data depend on appropriate equipment, calibration, resolution, consistent technique and a sample size that represents genuine independent evidence rather than repeated digital readings of the same event.','examples':[('Choose appropriate resolution','If temperature changes of about 0.2 °C matter, a thermometer marked only every 1 °C cannot resolve the required change reliably.'),('Check zero and calibration','A balance that reads 0.6 g when empty has a systematic offset. Zeroing or recalibrating it is required before interpreting measurements.'),('Sampling rate is not sample size','A motion sensor recording 100 values in one run gives many data points, but it is still one experimental run. Independent repeats provide stronger replicability evidence.'),('Record uncertainty honestly','If a ruler is marked in millimetres, reporting a length as 12.347826 cm implies precision the instrument did not provide.')],'mis':[('Precise means accurate','Precision describes closeness or resolution; accuracy is closeness to the accepted or true value.'),('More decimal places mean better data','Reported precision must match the measuring instrument and method.'),('A large file means a large sample','Many readings from one run may not be independent observations.'),('Human error explains every anomaly','Name the specific mechanism: parallax, timing delay, inconsistent endpoint, calibration or another plausible source.')],'steps':[('Match equipment to purpose','Select range, sensitivity and resolution appropriate to expected values.'),('Calibrate and standardise','Check zero/reference points and use the same measurement technique.'),('Collect independent evidence','Use an appropriate number of samples or repeated trials, not just a high digital sampling rate.'),('Record with units and limits','Store raw values, units, relevant uncertainty and enough metadata for replication.')],'transfer':'Two groups measure the period of a pendulum. One times a single swing with a phone stopwatch; the other times 20 swings and divides by 20. Compare the precision and likely sources of uncertainty.'},
'AC9S10I04':{'title':'Represent Data Without Distortion','summary':'Tables, graphs, descriptive statistics, models and equations are tools for revealing patterns. The best representation matches the data and purpose, follows scientific conventions and makes uncertainty or limitations visible rather than exaggerating a result.','examples':[('Select a graph for the variables','Continuous independent and dependent variables are often suited to a scatter or line graph; categories are usually clearer in a bar chart.'),('Expose a misleading scale','A y-axis starting at 98 can make a change from 100 to 102 look dramatic. The scale may be legitimate, but the visual effect must not be mistaken for a large proportional change.'),('Use statistics with context','Two samples can have the same mean but very different spread. Report range, distribution or uncertainty when it changes interpretation.'),('Compare model and observation','A line of best fit summarises a relationship; points away from the line are not automatically wrong and may reveal variation, uncertainty or another factor.')],'mis':[('The most complicated representation is best','Use the simplest form that answers the scientific question without hiding important variation.'),('Changing an axis only changes appearance','Scale changes perception and can influence the conclusion a viewer draws.'),('A mean tells the whole story','Spread, sample size, outliers and distribution can matter as much as the centre.'),('A model line is the data','The model is a summary or approximation; measured observations remain the evidence.')],'steps':[('Define the message','Decide which comparison, trend, distribution or relationship must be communicated.'),('Select the representation','Choose table, graph, statistic, model or equation that fits the variables and purpose.'),('Apply conventions','Include meaningful titles, labels, units, scales, keys and uncertainty where relevant.'),('Interrogate the display','Check whether scale, statistic or model could distort, hide or overstate the evidence.')],'transfer':'A graph of sea-level change uses a very narrow y-axis range. Explain one benefit and one risk of that choice, then state what additional representation would help a reader judge the magnitude fairly.'},
'AC9S10I05':{'title':'Analyse Patterns and Relationships in Evidence','summary':'Scientific analysis connects multiple sources of data and information to identify trends, patterns, relationships and anomalies. Conclusions should distinguish what the evidence shows from what is inferred and consider whether alternative explanations remain plausible.','examples':[('Identify a trend','If reaction rate rises consistently as temperature rises across repeated trials, describe the direction and strength of the pattern before explaining a mechanism.'),('Treat anomalies as evidence to investigate','One point far from the trend may reflect measurement error, natural variation or a real additional factor. Check method and context before excluding it.'),('Connect evidence sources','A climate conclusion is stronger when long-term temperature records, satellite observations and physical models support the same broad pattern.'),('Avoid causal overreach','A correlation between two variables does not by itself prove that one causes the other; confounders and mechanism must be considered.')],'mis':[('Every pattern is meaningful','Patterns can arise by chance, bias or confounding, especially with small samples.'),('An anomaly should always be deleted','Investigate its cause and justify inclusion or exclusion transparently.'),('Correlation proves causation','Causal claims need design, mechanism and exclusion of credible alternatives.'),('Analysis begins with an explanation','Describe the evidence pattern first, then use scientific reasoning to interpret it.')],'steps':[('Inspect the evidence','Check units, variables, sample size and data quality before calculating or interpreting.'),('Describe patterns precisely','Identify trends, clusters, differences, relationships and anomalies without adding unsupported causes.'),('Connect evidence and models','Use scientific knowledge to explain the pattern and compare evidence sources.'),('Test alternatives','Ask what other explanation, bias or limitation could produce the same evidence.')],'transfer':'A dataset shows a strong negative relationship between exercise time and resting heart rate. State what can be concluded from the pattern alone and what extra evidence would be needed for a causal claim.'},
'AC9S10I06':{'title':'Evaluate Validity, Reproducibility and Evidence Quality','summary':'Evaluation asks whether a method actually tested the intended question, whether another investigator could reproduce it, and whether the evidence is accurate, precise, representative and sufficient for the conclusion being claimed.','examples':[('Validity check','If a plant-growth experiment changes both fertiliser dose and light exposure, the effect of fertiliser cannot be isolated confidently.'),('Reproducibility check','A method that says heat gently until ready is difficult to reproduce because the endpoint and heating conditions are undefined.'),('Accuracy versus precision','Measurements can cluster tightly around the wrong value if an instrument is systematically miscalibrated.'),('Evidence sufficiency','A conclusion about an entire population based on one convenient sample may be precise for that sample but not representative.')],'mis':[('Reliable = valid','A procedure can give similar results repeatedly while consistently measuring the wrong thing.'),('One replication proves reproducibility','Reproducibility is supported by independent repetition under clearly reported conditions, not guaranteed by a single success.'),('Uncertainty makes data useless','Uncertainty is part of measurement and should be quantified or discussed, not hidden.'),('Evaluation means listing human error','Name specific sources, explain their likely direction or effect and propose realistic improvements.')],'steps':[('Audit alignment','Does the method test the question and control the main competing variables?'),('Audit reproducibility','Could another investigator reproduce the procedure from the information given?'),('Audit measurement quality','Consider calibration, resolution, sample size, bias, random variation and uncertainty.'),('Judge the conclusion','Decide whether the strength and scope of the claim match the evidence and state the most important limitation.')],'transfer':'A study reports a 3% difference between treatments, but measuring uncertainty is ±4%. Evaluate whether the evidence supports a meaningful difference and what should be improved.'},
'AC9S10I07':{'title':'Construct Evidence-Based Scientific Arguments','summary':'A scientific argument links a clear claim to relevant evidence and scientific reasoning, evaluates competing explanations and acknowledges limitations. Strong arguments can change when better evidence becomes available.','examples':[('Claim–evidence–reasoning','Claim: increasing temperature increased reaction rate. Evidence: mean reaction time fell across all temperature conditions. Reasoning: higher particle kinetic energy increases successful collision frequency.'),('Compare competing explanations','If two mechanisms could explain the same pattern, state what each predicts and identify evidence that would discriminate between them.'),('Use evidence proportionately','A small observational dataset may justify a tentative claim but not a universal conclusion.'),('Address counterevidence','Evidence that does not fit the preferred explanation should be examined, not ignored; it may reveal a limitation or a better model.')],'mis':[('Argument means opinion','Scientific arguments are evidence-based and open to revision.'),('More evidence automatically means stronger evidence','Relevance, independence and quality matter more than quantity alone.'),('Counterevidence should be excluded','A strong argument addresses credible conflicting evidence explicitly.'),('Confidence means certainty','Use language that matches the strength and limitations of the evidence.')],'steps':[('State the claim precisely','Make the scope of the conclusion clear and avoid broader claims than the evidence supports.'),('Select relevant evidence','Choose observations or data that directly bear on the claim and identify their quality.'),('Explain the reasoning','Use scientific concepts or models to show why the evidence supports the claim.'),('Evaluate alternatives and limitations','Address credible counterarguments, uncertainty and what new evidence could change the conclusion.')],'transfer':'Two explanations are proposed for declining frog numbers: habitat loss and disease. Outline an argument that uses evidence to compare them rather than assuming only one factor can operate.'},
'AC9S10I08':{'title':'Communicate Scientific Ideas, Findings and Arguments','summary':'Scientific communication selects language, structure, data displays and level of detail for a particular audience and purpose. It must distinguish evidence from interpretation, represent uncertainty honestly and acknowledge sources and limitations.','examples':[('Adapt to audience without changing meaning','A technical report may use 95% confidence interval; a public summary can explain the same uncertainty in plain language without pretending the estimate is exact.'),('Integrate a figure with prose','Do not insert a graph without interpretation. State the pattern the figure supports, refer to the variables and explain why it matters to the argument.'),('Distinguish result from conclusion','Result: the treated group had a lower mean value. Conclusion: under these conditions, the treatment is associated with a reduction; further work is needed before generalising.'),('Cite evidence and limitations','A persuasive scientific text still identifies data sources, uncertainties, assumptions and competing explanations rather than hiding them.')],'mis':[('Simplifying means removing uncertainty','Audience-friendly language must preserve the strength and limits of the evidence.'),('A graph speaks for itself','Every representation needs context, labels and interpretation.'),('Scientific writing must be passive and complicated','Clarity and precision matter more than unnecessarily complex wording.'),('Communication happens after reasoning is finished','Choosing what to show can expose gaps in evidence and improve the analysis itself.')],'steps':[('Define audience and purpose','Decide what the audience needs to know and what background can be assumed.'),('Select evidence and representations','Choose relevant data, figures, models or examples and label them accurately.'),('Build a logical explanation','Structure claim, evidence, reasoning, limitations and implications so the argument can be followed.'),('Review for accuracy and accessibility','Check terminology, units, source attribution, uncertainty, visual integrity and whether simplification changed the scientific meaning.')],'transfer':'Rewrite a technical finding about a 12% increase with a wide uncertainty range for a community newsletter. Preserve the uncertainty and avoid overstating the result.'}}

def clean(s): return re.sub(r'\s+',' ',html.unescape(re.sub(r'<[^>]+>',' ',str(s or '')))).strip()
def esc(s): return html.escape(str(s),quote=True)
def extract_list(src,heading):
 m=re.search(rf'<h3>{re.escape(heading)}</h3><ul>(.*?)</ul>',src,re.I|re.S); return [] if not m else [clean(x) for x in re.findall(r'<li>(.*?)</li>',m.group(1),re.S)]
def elaborations(src):
 b=re.search(r'<summary><strong>Australian Curriculum elaborations</strong></summary><div class="curriculum-detail-body">(.*?)</div></details>',src,re.I|re.S)
 return [] if not b else [clean(x) for x in re.findall(r'<article.*?<p>(.*?)</p>',b.group(1),re.I|re.S)]
def cards(items): return ''.join(f'<article class="curriculum-worked-example"><h3>{esc(a)}</h3><p>{esc(b)}</p></article>' for a,b in items)
def bullets(items): return ''.join(f'<li><strong>{esc(a)}:</strong> {esc(b)}</li>' for a,b in items)
def render(code,p,must,dont,els):
 core=''.join(f'<li>{esc(x)}</li>' for x in (must or [p['summary']]))
 bound=''.join(f'<li>{esc(x)}</li>' for x in dont)
 cov=''.join(f'<li><strong>E{i+1}:</strong> {esc(x)}</li>' for i,x in enumerate(els)) or '<li>Use the exact content description as the required target and treat elaborations as teaching examples.</li>'
 return f'''<details class="curriculum-topic-section" open><summary><strong>Core concepts and success criteria</strong></summary><div class="curriculum-detail-body"><p>{esc(p['summary'])}</p><h3>What students need to know</h3><ul>{core}</ul><p><strong>Success looks like:</strong> students can apply the inquiry skill to a new context, justify methodological choices and match the strength of a conclusion to the evidence.</p></div></details><details class="curriculum-topic-section"><summary><strong>Worked examples</strong></summary><div class="curriculum-detail-body">{cards(p['examples'])}</div></details><details class="curriculum-topic-section"><summary><strong>Common misconceptions and fixes</strong></summary><div class="curriculum-detail-body"><ul>{bullets(p['mis'])}</ul></div></details><details class="curriculum-topic-section"><summary><strong>Step-by-step inquiry method</strong></summary><div class="curriculum-detail-body"><div class="unit-activity-grid">{cards(p['steps'])}</div>{('<h3>Boundary / do not overteach</h3><ul>'+bound+'</ul>') if bound else ''}</div></details><details class="curriculum-topic-section"><summary><strong>Apply and transfer</strong></summary><div class="curriculum-detail-body"><p>{esc(p['transfer'])}</p><p><strong>Student check:</strong> answer using specific variables, evidence, method choices or limitations rather than generic phrases such as human error.</p></div></details><details class="curriculum-topic-section"><summary><strong>Australian Curriculum coverage</strong></summary><div class="curriculum-detail-body"><p>The content description is the required target. These elaborations are breadth examples and should be taught through authentic inquiry contexts rather than memorised as a checklist.</p><ul>{cov}</ul></div></details><details class="curriculum-topic-section"><summary><strong>International curriculum mapping</strong></summary><div class="curriculum-detail-body"><p><strong>Australia:</strong> Australian Curriculum v9.0 {code} (exact SkillrHub outcome).</p><p><strong>United States:</strong> closest alignment is NGSS science and engineering practices involving investigations, data analysis, arguments and scientific communication according to this code's focus.</p><p><strong>England:</strong> closest alignment is secondary/GCSE Working Scientifically.</p><p><strong>New Zealand:</strong> closest alignment is the Nature of Science strand, especially investigating and communicating in science.</p><p><strong>Canada:</strong> closest alignment is provincial secondary Science inquiry, investigation and communication expectations; exact wording varies by province.</p><p>These are planning comparisons, not exact one-to-one equivalences.</p></div></details><details class="curriculum-topic-section"><summary><strong>Resources</strong></summary><div class="curriculum-detail-body"><div class="curriculum-link-row"><a class="curriculum-button primary" href="teacher-slides/">Teacher Slides</a><a class="curriculum-button" href="/quiz/year-10/science/{code.lower()}/worksheet/">Practice Sheet</a><a class="curriculum-button" href="/quiz/year-10/science/{code.lower()}/practice/">Practice</a><a class="curriculum-button" href="/quiz/year-10/science/{code.lower()}/test/">Test</a></div></div></details>'''
def upgrade(path):
 src=path.read_text(encoding='utf-8'); m=re.search(r'AC9S10I\d{2}',src)
 if not m:return False
 code=m.group(0); p=PROFILES[code]; must=extract_list(src,'Must teach'); dont=extract_list(src,'Do not overteach'); els=elaborations(src)
 start=src.find('<main class="curriculum-layout"><div id="topic-guide">'); aside=src.find('<aside class="curriculum-sidebar">',start)
 if start<0 or aside<0: raise RuntimeError(f'anchors not found: {path}')
 out=src[:start]+'<main class="curriculum-layout"><div id="topic-guide">'+render(code,p,must,dont,els)+'</div>'+src[aside:]
 out=re.sub(r'<h1>.*?</h1>',f'<h1>{esc(p["title"])}</h1>',out,count=1,flags=re.S)
 out=re.sub(r'<p class="curriculum-hero__lead">.*?</p>',f'<p class="curriculum-hero__lead">{esc(p["summary"])}</p>',out,count=1,flags=re.S)
 meta=f"{code} Year 10 Science Inquiry lesson: {p['summary']} Includes worked examples, misconceptions, transfer practice and curriculum mapping."
 out=re.sub(r'<meta name="description" content="[^"]*">',f'<meta name="description" content="{esc(meta)}">',out,count=1)
 if out!=src:path.write_text(out,encoding='utf-8');return True
 return False
def main():
 pages=sorted(BASE.glob('ac9s10i*/index.html'))
 if len(pages)!=8: raise SystemExit(f'Expected 8 Year 10 Science Inquiry pages, found {len(pages)}')
 changed=sum(int(upgrade(p)) for p in pages); print(f'Re-authored {changed} of {len(pages)} Year 10 Science Inquiry topic pages.')
if __name__=='__main__':main()
